import{_ as a,o as e,c as r,a2 as d}from"./chunks/framework.BqDA2HS7.js";const v=JSON.parse('{"title":"Advisor Gate · 审核","description":"","frontmatter":{},"headers":[],"relativePath":"strategies/advisor.md","filePath":"strategies/advisor.md"}'),o={name:"strategies/advisor.md"};function i(s,t,n,h,l,p){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="advisor-gate-·-审核" tabindex="-1">Advisor Gate · 审核 <a class="header-anchor" href="#advisor-gate-·-审核" aria-label="Permalink to &quot;Advisor Gate · 审核&quot;">​</a></h1><p>Advisor 使用固定执行器，在准备交付最终回复时审核候选。 默认最多 <strong>两次审核、一次返工</strong>，最终或复审通过才交付。</p><h2 id="审核闭环" tabindex="-1">审核闭环 <a class="header-anchor" href="#审核闭环" aria-label="Permalink to &quot;审核闭环&quot;">​</a></h2><table tabindex="0"><thead><tr><th>边界与判定</th><th>行为</th></tr></thead><tbody><tr><td>正常工具请求</td><td>交给宿主执行，不做结束轮审核</td></tr><tr><td>首次最终候选 APPROVE</td><td>放行候选</td></tr><tr><td>首次最终候选 REDO</td><td>丢弃候选，保存反馈，请原执行器修正</td></tr><tr><td>返工需要工具</td><td>宿主正常执行，反馈与计数跨请求保留</td></tr><tr><td>修正后的最终候选 APPROVE</td><td>放行并标记复审通过</td></tr><tr><td>第二次未通过，或无法判断</td><td>未审定停止，不交付该候选</td></tr></tbody></table><p>被丢弃内容只保留在审计记录，不能作为已接受历史。返工不重新执行已完成工具。 停滞审核只保留在旧兼容路径，本版严格 Gate 不增加每轮工具审核。</p><h2 id="在哪里选择-jev" tabindex="-1">在哪里选择 Jev <a class="header-anchor" href="#在哪里选择-jev" aria-label="Permalink to &quot;在哪里选择 Jev&quot;">​</a></h2><p>进入 <strong>规划路由 → 正在编辑的策略：Advisor → 审核器类型</strong>，选择官方 Jev。 再在官方 Jev 的渠道、凭证引用和数据域设置中核对 OpenRouter。 不是在“Advisor 审核 LLM（DSH 模型）”的模型下拉框里寻找 Jev。</p><p>该下拉框只用于 LLM 后端；本地 Laya 也是独立审核器类型，不是普通 DSH 生成模型。 当前 Laya 审核质量标为实验；选择它需要显式接受实验状态并提前就绪。</p><h2 id="判别与故障" tabindex="-1">判别与故障 <a class="header-anchor" href="#判别与故障" aria-label="Permalink to &quot;判别与故障&quot;">​</a></h2><p>审核检查用户要求、已接受历史、工具证据和候选；复审包含前次问题与反馈。 LLM 输出严格校验；非法结构、超容量、认证／传输故障或未知用量停止，不自动修复 Judge。 本地输入不截断，结果分数不解释为正确率。</p><h2 id="费用与等待" tabindex="-1">费用与等待 <a class="header-anchor" href="#费用与等待" aria-label="Permalink to &quot;费用与等待&quot;">​</a></h2><p>执行前保护执行、首审、必要返工及复审的完整路径。 返工工具续接每轮另检查执行额度并继续保护复审；不能保证任意长返工必有预算完成。 候选缓冲与审核增加用户等待，未接受的候选不会闪现。</p><h2 id="轨迹应该看到什么" tabindex="-1">轨迹应该看到什么 <a class="header-anchor" href="#轨迹应该看到什么" aria-label="Permalink to &quot;轨迹应该看到什么&quot;">​</a></h2><p>首次审核、返工中、等待复审、已通过或未审定停止；原始结论、接受／丢弃、反馈、 模型首字时间、审核等待、费用与保护额度。Judge 批准不替代团队对实际质量的验收。</p>',14)])])}const _=a(o,[["render",i]]);export{v as __pageData,_ as default};
